fn write_temp_file(name: &str, contents: &str) -> std::path::PathBuf {
    let path = std::env::temp_dir().join(format!("lalapad-{name}-{}.toml", std::process::id()));
    std::fs::write(&path, contents).unwrap();
    path
}

fn makefile_task_block(task: &str) -> &str {
    let marker = format!("[tasks.{task}]");
    let start = MAKEFILE_TOML
        .find(&marker)
        .unwrap_or_else(|| panic!("Makefile.toml is missing {marker}"));
    let after_marker = start + marker.len();
    let rest = &MAKEFILE_TOML[after_marker..];
    let end = rest
        .find("\n[tasks.")
        .map(|offset| after_marker + offset)
        .unwrap_or(MAKEFILE_TOML.len());
    &MAKEFILE_TOML[start..end]
}

fn assert_task_prefers_sibling_zmk_checkout(task: &str, block: &str) {
    let sibling = "../zmk-config-LalaPadGen2/config/lalapadgen2.keymap";
    let local = "zmk-config-LalaPadGen2/config/lalapadgen2.keymap";
    let sibling_index = block
        .find(sibling)
        .unwrap_or_else(|| panic!("{task} should resolve the sibling ZMK checkout"));
    let local_index = block
        .find(local)
        .unwrap_or_else(|| panic!("{task} should resolve the CI-local ZMK checkout"));
    assert!(
        sibling_index < local_index,
        "{task} should match porting_coverage.py default ZMK keymap resolution order"
    );
}

fn complete_hardware_evidence_overlay(firmware_ref: &str) -> String {
    let manifest = hardware_validation_manifest_toml();
    let mut evidence = String::from("# Generated by host parity tests.\n");
    for check in manifest["checks"].as_array().unwrap() {
        let check_id = check["id"].as_str().unwrap();
        let evidence_needles = check["evidence_needles"]
            .as_array()
            .map(|needles| {
                needles
                    .iter()
                    .map(|needle| needle.as_str().unwrap())
                    .collect::<Vec<_>>()
                    .join("; ")
            })
            .unwrap_or_default();
        evidence.push_str("\n[[evidence]]\n");
        evidence.push_str(&format!("id = \"{check_id}\"\n"));
        evidence.push_str("status = \"validated\"\n");
        evidence.push_str("validated_at = \"2026-05-29\"\n");
        evidence.push_str("tester = \"host parity test\"\n");
        evidence.push_str(&format!("firmware_ref = \"{firmware_ref}\"\n"));
        evidence.push_str(&format!(
            "artifact_or_notes = \"log: /tmp/lalapad-host-parity-{check_id}.txt; simulated host gate evidence for {check_id}; observed {evidence_needles}\"\n",
        ));
    }
    evidence
}

fn complete_hardware_evidence_overlay_with_pair_sha(
    firmware_ref: &str,
    pair_sha256: &str,
) -> String {
    complete_hardware_evidence_overlay(firmware_ref).replace(
        "observed",
        &format!("firmware artifact pair_sha256 {pair_sha256}; observed"),
    )
}

fn test_firmware_artifact_fixture(
    firmware_ref: &str,
) -> (std::path::PathBuf, std::path::PathBuf, String) {
    let root = std::env::temp_dir().join(format!(
        "lalapad-firmware-artifacts-{}-{firmware_ref}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&root);
    for (path, contents) in [
        (
            "firmware/normal/lalapad-gen2-rmk-central.uf2",
            b"central uf2".as_slice(),
        ),
        (
            "firmware/normal/lalapad-gen2-rmk-peripheral.uf2",
            b"peripheral uf2".as_slice(),
        ),
    ] {
        let target = root.join(path);
        std::fs::create_dir_all(target.parent().unwrap()).unwrap();
        std::fs::write(target, contents).unwrap();
    }
    let manifest_path = root.join("firmware-artifacts.local.json");
    let output = Command::new("python3")
        .arg("tools/firmware_artifact_manifest.py")
        .arg("--root")
        .arg(&root)
        .arg("--firmware-ref")
        .arg(firmware_ref)
        .arg("--require-uf2")
        .arg("--output")
        .arg(&manifest_path)
        .current_dir(env!("CARGO_MANIFEST_DIR"))
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "failed to generate test firmware artifact manifest\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&manifest_path).unwrap()).unwrap();
    let pair_sha256 = parsed["pair_sha256"].as_str().unwrap().to_string();
    (root, manifest_path, pair_sha256)
}

fn run_python(script: &str) -> std::process::Output {
    Command::new("python3")
        .arg("-c")
        .arg(script)
        .current_dir(env!("CARGO_MANIFEST_DIR"))
        .output()
        .unwrap()
}

fn default_zmk_config_dir() -> Option<std::path::PathBuf> {
    for relative in [
        "../zmk-config-LalaPadGen2/config",
        "zmk-config-LalaPadGen2/config",
    ] {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(relative);
        if path.join("lalapadgen2.keymap").exists() {
            return Some(path);
        }
    }
    None
}

fn manifest_status_counts(manifest: &toml::Value) -> BTreeMap<String, i64> {
    let mut counts = BTreeMap::new();
    for section in ["iqs9151_register_porting", "iqs9151_bit_porting"] {
        for entry in manifest[section].as_array().unwrap() {
            let status = entry["status"].as_str().unwrap().to_string();
            *counts.entry(status).or_insert(0) += 1;
        }
    }
    counts
}

