#[test]
fn porting_coverage_complete_gate_accepts_explicit_status_completion() {
    let output = run_porting_coverage(&[
        "--coverage-baseline",
        "tools/porting_coverage_baseline.toml",
        "--require-porting-complete",
    ]);

    assert!(
        output.status.success(),
        "complete porting gate failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    let baseline = porting_coverage_baseline_toml();
    let baseline_by_kind = baseline["coverage"]["by_kind"].as_table().unwrap();
    for kind in ["build_task", "dependency", "runtime_scenario"] {
        let expected = baseline_by_kind[kind].as_table().unwrap();
        let passed = expected["passed"].as_integer().unwrap();
        let total = expected["total"].as_integer().unwrap();
        assert!(stdout.contains(&format!("- {kind}: {passed}/{total} = 100.00%")));
    }
    assert!(stdout.contains("Porting coverage by kind:"));
    assert!(stdout.contains("- code_topology: 54/54 = 100.00%"));
    assert!(stdout.contains("- gpio_flag_mirror: 36/36 = 100.00%"));
    let release_workflow = baseline_by_kind["release_workflow"].as_table().unwrap();
    let release_passed = release_workflow["passed"].as_integer().unwrap();
    let release_total = release_workflow["total"].as_integer().unwrap();
    assert!(stdout.contains(&format!(
        "- release_workflow: {release_passed}/{release_total} = 100.00%"
    )));
    assert!(stdout.contains("- rmk_patch: 59/59 = 100.00%"));
    assert!(stdout.contains("- scenario:"));
    assert!(stdout.contains("- split: 100/100 = 100.00%"));
    assert!(stdout.contains("- trackpad_virtual: 66/66 = 100.00%"));
    assert!(stdout.contains("- vial: 332/332 = 100.00%"));
    assert!(stdout.contains("- vial_user_key_semantics: 57/57 = 100.00%"));
    assert!(stdout.contains("- zmk_source_cell:"));
    assert!(stdout.contains("Porting status: 69/69 = 100.00% implemented"));
    assert!(stdout.contains("ZMK source: path="));
    assert!(stdout.contains("git_commit="));
}

#[test]
fn migration_dashboards_report_zmk_source_reference() {
    let Some(zmk_config_dir) = default_zmk_config_dir() else {
        return;
    };
    let zmk_keymap = zmk_config_dir.join("lalapadgen2.keymap");
    let zmk_keymap = zmk_keymap.to_str().unwrap();

    let coverage = run_porting_coverage(&[
        "--json",
        "--zmk-keymap",
        zmk_keymap,
        "--require-zmk-source",
        "--require-zmk-source-commit",
    ]);
    assert!(
        coverage.status.success(),
        "porting coverage failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&coverage.stdout),
        String::from_utf8_lossy(&coverage.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&coverage.stdout).unwrap();
    assert_eq!(
        parsed["zmk_source_commit_errors"].as_array().unwrap().len(),
        0,
        "the default ZMK source checkout should match metadata.source_commit"
    );
    let zmk_source = &parsed["zmk_source"];
    let manifest = porting_coverage_manifest_toml();
    let expected_source_commit = manifest["metadata"]["source_commit"].as_str().unwrap();
    assert_eq!(zmk_source["available"].as_bool(), Some(true));
    assert!(
        zmk_source["keymap_path"]
            .as_str()
            .unwrap()
            .ends_with("config/lalapadgen2.keymap")
    );
    if let Some(commit) = zmk_source["git_commit"]
        .as_str()
        .filter(|commit| !commit.is_empty())
    {
        assert_eq!(
            commit, expected_source_commit,
            "ZMK source git_commit should match the manifest-pinned source commit"
        );
        assert!(
            commit.len() == 40 && commit.chars().all(|ch| ch.is_ascii_hexdigit()),
            "ZMK source git_commit should be a full immutable commit hash, got {commit:?}"
        );
    }
    assert!(
        zmk_source["git_dirty"].is_boolean() || zmk_source["git_dirty"].is_null(),
        "ZMK source dirty state should be reported as a boolean or unknown"
    );
    assert!(
        zmk_source["git_dirty_paths"].as_array().is_some(),
        "ZMK source JSON should include the dirty path inventory"
    );
    assert!(
        zmk_source["repo_path"]
            .as_str()
            .is_some_and(|repo| !repo.is_empty()),
        "ZMK source JSON should include the Git repository path when available"
    );

    let migration = run_migration_status(&[
        "--json",
        "--coverage-baseline",
        "tools/porting_coverage_baseline.toml",
        "--hardware-baseline",
        "tools/hardware_validation_baseline.toml",
        "--zmk-keymap",
        zmk_keymap,
        "--require-zmk-source",
        "--require-zmk-source-commit",
        "--require-software-complete",
        "--require-hardware-classified",
    ]);
    assert!(
        migration.status.success(),
        "migration status failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&migration.stdout),
        String::from_utf8_lossy(&migration.stderr)
    );
    let migration_json: serde_json::Value = serde_json::from_slice(&migration.stdout).unwrap();
    assert_eq!(
        migration_json["software"]["zmk_source"]["keymap_path"],
        parsed["zmk_source"]["keymap_path"]
    );

    let migration_text = run_migration_status(&[
        "--coverage-baseline",
        "tools/porting_coverage_baseline.toml",
        "--hardware-baseline",
        "tools/hardware_validation_baseline.toml",
        "--zmk-keymap",
        zmk_keymap,
        "--require-zmk-source",
    ]);
    assert!(
        String::from_utf8_lossy(&migration_text.stdout).contains("ZMK source: path=")
            && String::from_utf8_lossy(&migration_text.stdout).contains(" repo="),
        "text migration dashboard should show the ZMK source reference"
    );

    let migration_markdown = run_migration_status(&[
        "--markdown",
        "--coverage-baseline",
        "tools/porting_coverage_baseline.toml",
        "--hardware-baseline",
        "tools/hardware_validation_baseline.toml",
        "--zmk-keymap",
        zmk_keymap,
        "--require-zmk-source",
    ]);
    let markdown_stdout = String::from_utf8_lossy(&migration_markdown.stdout);
    assert!(
        markdown_stdout.contains("ZMK source:")
            && markdown_stdout.contains("repo=`")
            && markdown_stdout.contains("git_commit=`")
            && markdown_stdout.contains("dirty_paths=`"),
        "Markdown migration dashboard should show the ZMK source repo and commit"
    );
}

#[test]
fn zmk_source_commit_gate_rejects_source_commit_drift() {
    let Some(zmk_config_dir) = default_zmk_config_dir() else {
        return;
    };
    let zmk_keymap = zmk_config_dir.join("lalapadgen2.keymap");
    let zmk_keymap = zmk_keymap.to_str().unwrap();

    let output = run_python(
        r#"
import json
import sys

sys.path.insert(0, "tools")
import porting_coverage as pc

manifest = pc.load_toml(pc.Path("tools/porting_coverage_manifest.toml"))
expected = pc.manifest_zmk_source_commit(manifest)
matching = {"git_commit": expected}
wrong = {"git_commit": "0" * 40}
missing = dict(manifest)
missing["metadata"] = dict(missing.get("metadata", {}))
missing["metadata"].pop("source_commit", None)
print(json.dumps({
    "expected": expected,
    "matching_errors": pc.zmk_source_commit_errors(manifest, matching),
    "wrong_errors": pc.zmk_source_commit_errors(manifest, wrong),
    "missing_errors": pc.zmk_source_commit_errors(missing, matching),
}, sort_keys=True))
"#,
    );
    assert!(
        output.status.success(),
        "ZMK source commit helper fixture failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let expected = parsed["expected"].as_str().unwrap();
    assert_eq!(expected.len(), 40);
    assert_eq!(parsed["matching_errors"].as_array().unwrap().len(), 0);
    assert!(
        parsed["wrong_errors"][0]
            .as_str()
            .unwrap()
            .contains("metadata.source_commit")
    );
    assert!(
        parsed["missing_errors"][0]
            .as_str()
            .unwrap()
            .contains("metadata.source_commit")
    );

    let bad_manifest = write_temp_file(
        "bad-zmk-source-commit",
        &PORTING_COVERAGE_MANIFEST_TOML.replace(expected, &"1".repeat(40)),
    );
    let bad_manifest = bad_manifest.to_str().unwrap().to_owned();
    let migration = run_migration_status(&[
        "--porting-manifest",
        &bad_manifest,
        "--zmk-keymap",
        zmk_keymap,
        "--require-zmk-source",
        "--require-zmk-source-commit",
    ]);
    assert!(
        !migration.status.success(),
        "migration status should reject source commit drift\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&migration.stdout),
        String::from_utf8_lossy(&migration.stderr)
    );
    assert!(
        String::from_utf8_lossy(&migration.stdout).contains("zmk_source_commit")
            && String::from_utf8_lossy(&migration.stderr)
                .contains("ZMK source commit does not match")
    );
}

#[test]
fn zmk_source_clean_gate_rejects_dirty_source_repositories() {
    let output = run_python(
        r#"
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

sys.path.insert(0, "tools")
import porting_coverage as pc

root = Path(tempfile.mkdtemp(prefix="lalapad-zmk-source-clean-"))
try:
    keymap = root / "config" / "lalapadgen2.keymap"
    keymap.parent.mkdir(parents=True)
    keymap.write_text("// source keymap\n", encoding="utf-8")
    subprocess.run(["git", "init"], cwd=root, check=True, stdout=subprocess.DEVNULL)
    subprocess.run(["git", "add", "config/lalapadgen2.keymap"], cwd=root, check=True)
    subprocess.run(
        [
            "git",
            "-c",
            "user.name=Porting Test",
            "-c",
            "user.email=porting-test@example.invalid",
            "commit",
            "-m",
            "source",
        ],
        cwd=root,
        check=True,
        stdout=subprocess.DEVNULL,
    )
    clean = pc.zmk_source_reference(keymap)
    clean_errors = pc.zmk_source_clean_errors(clean)
    keymap.write_text("// source keymap\n// local edit\n", encoding="utf-8")
    dirty = pc.zmk_source_reference(keymap)
    dirty_errors = pc.zmk_source_clean_errors(dirty)
    print(json.dumps({
        "clean": clean,
        "clean_errors": clean_errors,
        "dirty": dirty,
        "dirty_errors": dirty_errors,
    }, sort_keys=True))
finally:
    shutil.rmtree(root, ignore_errors=True)
"#,
    );
    assert!(
        output.status.success(),
        "ZMK clean-source fixture failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(parsed["clean"]["available"].as_bool(), Some(true));
    assert_eq!(parsed["clean"]["git_dirty"].as_bool(), Some(false));
    assert_eq!(
        parsed["clean"]["git_dirty_paths"].as_array().unwrap().len(),
        0
    );
    assert_eq!(parsed["clean_errors"].as_array().unwrap().len(), 0);
    assert_eq!(parsed["dirty"]["git_dirty"].as_bool(), Some(true));
    assert_eq!(
        parsed["dirty"]["git_dirty_paths"][0].as_str(),
        Some("config/lalapadgen2.keymap")
    );
    assert!(
        parsed["dirty_errors"]
            .as_array()
            .unwrap()
            .iter()
            .any(|error| error
                .as_str()
                .unwrap()
                .contains("config/lalapadgen2.keymap")),
        "dirty ZMK source should fail the clean-source gate"
    );
}

#[test]
fn porting_coverage_requires_evidence_for_non_direct_porting_statuses() {
    let output = run_porting_coverage(&["--json"]);
    assert!(
        output.status.success(),
        "porting coverage failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let evidence_bucket = &parsed["by_kind"]["porting_status_evidence"];
    assert_eq!(evidence_bucket["passed"], evidence_bucket["total"]);
    assert_eq!(evidence_bucket["total"].as_i64(), Some(34));

    let missing_evidence_manifest = PORTING_COVERAGE_MANIFEST_TOML.replacen(
        "evidence = [\n  \"rust_byte_array:iqs9151_main_config_bytes\",\n  \"code:iqs9151_config_image_write_path\",\n]\n",
        "",
        1,
    );
    let missing_path = write_temp_file(
        "porting-coverage-missing-status-evidence",
        &missing_evidence_manifest,
    );
    let missing = run_porting_coverage(&["--manifest", missing_path.to_str().unwrap()]);
    let _ = std::fs::remove_file(&missing_path);
    assert!(
        !missing.status.success(),
        "porting coverage accepted missing non-direct status evidence\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&missing.stdout),
        String::from_utf8_lossy(&missing.stderr)
    );
    let missing_stdout = String::from_utf8_lossy(&missing.stdout);
    assert!(missing_stdout.contains("porting_status_evidence"));
    assert!(missing_stdout.contains("has no evidence refs"));

    let stale_evidence_manifest = PORTING_COVERAGE_MANIFEST_TOML.replacen(
        "rust_const:two_finger_pinch_wheel_gain",
        "rust_const:missing_pinch_evidence",
        1,
    );
    let stale_path = write_temp_file(
        "porting-coverage-stale-status-evidence",
        &stale_evidence_manifest,
    );
    let stale = run_porting_coverage(&["--manifest", stale_path.to_str().unwrap()]);
    let _ = std::fs::remove_file(&stale_path);
    assert!(
        !stale.status.success(),
        "porting coverage accepted stale non-direct status evidence\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&stale.stdout),
        String::from_utf8_lossy(&stale.stderr)
    );
    assert!(String::from_utf8_lossy(&stale.stdout).contains("did not match any result"));

    let misleading_evidence_manifest = PORTING_COVERAGE_MANIFEST_TOML.replacen(
        "rust_const:two_finger_pinch_wheel_gain",
        "rust_const:trackpad_dynamic_scale_default",
        1,
    );
    let misleading_path = write_temp_file(
        "porting-coverage-misleading-status-evidence",
        &misleading_evidence_manifest,
    );
    let misleading = run_porting_coverage(&[
        "--manifest",
        misleading_path.to_str().unwrap(),
        "--coverage-baseline",
        "tools/porting_coverage_baseline.toml",
    ]);
    let _ = std::fs::remove_file(&misleading_path);
    assert!(
        !misleading.status.success(),
        "porting coverage baseline accepted misleading but passing status evidence\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&misleading.stdout),
        String::from_utf8_lossy(&misleading.stderr)
    );
    assert!(
        String::from_utf8_lossy(&misleading.stderr).contains("coverage.result_inventory_sha256")
    );
}

#[test]
fn porting_coverage_requires_active_rust_unit_test_evidence() {
    let output = run_python(
        r##"
import importlib.util
import json
import shutil
import sys
import tempfile
from pathlib import Path

spec = importlib.util.spec_from_file_location("porting_coverage", "tools/porting_coverage.py")
pc = importlib.util.module_from_spec(spec)
sys.modules[spec.name] = pc
spec.loader.exec_module(pc)

manifest = pc.load_toml(Path("tools/porting_coverage_manifest.toml"))
ok = pc.check_rust_unit_tests(manifest, Path("."))

with tempfile.TemporaryDirectory() as root_dir:
    root = Path(root_dir)
    (root / "src").mkdir()
    iqs = Path("src/iqs9151.rs").read_text(encoding="utf-8")
    iqs = iqs.replace(
        "    #[test]\n    fn emits_pinch_button_and_wheel_for_two_finger_distance_motion()",
        "    #[test]\n    #[ignore]\n    fn emits_pinch_button_and_wheel_for_two_finger_distance_motion()",
        1,
    )
    (root / "src" / "iqs9151.rs").write_text(iqs, encoding="utf-8")
    ignored = pc.check_rust_unit_tests(manifest, root)

with tempfile.TemporaryDirectory() as root_dir:
    root = Path(root_dir)
    (root / "src").mkdir()
    iqs = Path("src/iqs9151.rs").read_text(encoding="utf-8")
    iqs = iqs.replace(
        "    #[test]\n    fn emits_pinch_button_and_wheel_for_two_finger_distance_motion()",
        "    #[test]\n    #[cfg_attr(all(), ignore)]\n    fn emits_pinch_button_and_wheel_for_two_finger_distance_motion()",
        1,
    )
    (root / "src" / "iqs9151.rs").write_text(iqs, encoding="utf-8")
    cfg_ignored = pc.check_rust_unit_tests(manifest, root)

with tempfile.TemporaryDirectory() as root_dir:
    root = Path(root_dir)
    (root / "src").mkdir()
    iqs = Path("src/iqs9151.rs").read_text(encoding="utf-8")
    iqs = iqs.replace(
        "    #[test]\n    fn emits_scroll_for_two_finger_centroid_motion()",
        "    fn emits_scroll_for_two_finger_centroid_motion()",
        1,
    )
    (root / "src" / "iqs9151.rs").write_text(iqs, encoding="utf-8")
    missing_test_attr = pc.check_rust_unit_tests(manifest, root)

with tempfile.TemporaryDirectory() as root_dir:
    root = Path(root_dir)
    (root / "src").mkdir()
    iqs = Path("src/iqs9151.rs").read_text(encoding="utf-8")
    iqs = iqs.replace(
        "    #[test]\n    fn emits_scroll_for_two_finger_centroid_motion()",
        "    #[test]\n    // The evidence checker should tolerate comments between attributes and fn.\n    pub fn emits_scroll_for_two_finger_centroid_motion()",
        1,
    )
    (root / "src" / "iqs9151.rs").write_text(iqs, encoding="utf-8")
    public_with_comment = pc.check_rust_unit_tests(manifest, root)

def pack(results):
    return [result.__dict__ | {"ok": result.ok} for result in results]

print(json.dumps({
    "ok": pack(ok),
    "ignored": pack(ignored),
    "cfg_ignored": pack(cfg_ignored),
    "missing_test_attr": pack(missing_test_attr),
    "public_with_comment": pack(public_with_comment),
}))
"##,
    );

    assert!(
        output.status.success(),
        "rust unit test evidence active-test check failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert!(
        parsed["ok"]
            .as_array()
            .unwrap()
            .iter()
            .all(|result| result["ok"] == true)
    );

    let ignored = parsed["ignored"]
        .as_array()
        .unwrap()
        .iter()
        .find(|result| result["id"] == "iqs9151_pinch_behavior_test")
        .expect("pinch behavior unit-test evidence result is missing");
    assert_eq!(ignored["kind"], "rust_unit_test");
    assert_eq!(ignored["ok"], false);
    assert!(
        ignored["message"]
            .as_str()
            .unwrap()
            .contains("must not be ignored")
    );

    let cfg_ignored = parsed["cfg_ignored"]
        .as_array()
        .unwrap()
        .iter()
        .find(|result| result["id"] == "iqs9151_pinch_behavior_test")
        .expect("cfg-ignored pinch behavior unit-test evidence result is missing");
    assert_eq!(cfg_ignored["kind"], "rust_unit_test");
    assert_eq!(cfg_ignored["ok"], false);
    assert!(
        cfg_ignored["message"]
            .as_str()
            .unwrap()
            .contains("must not be ignored")
    );

    let missing_test_attr = parsed["missing_test_attr"]
        .as_array()
        .unwrap()
        .iter()
        .find(|result| result["id"] == "iqs9151_scroll_behavior_test")
        .expect("scroll behavior unit-test evidence result is missing");
    assert_eq!(missing_test_attr["kind"], "rust_unit_test");
    assert_eq!(missing_test_attr["ok"], false);
    assert!(
        missing_test_attr["message"]
            .as_str()
            .unwrap()
            .contains("must be marked #[test]")
    );

    let public_with_comment = parsed["public_with_comment"]
        .as_array()
        .unwrap()
        .iter()
        .find(|result| result["id"] == "iqs9151_scroll_behavior_test")
        .expect("public scroll behavior unit-test evidence result is missing");
    assert_eq!(public_with_comment["kind"], "rust_unit_test");
    assert_eq!(public_with_comment["ok"], true);
}

#[test]
fn porting_coverage_baseline_matches_current_denominator() {
    let output = run_porting_coverage(&[
        "--coverage-baseline",
        "tools/porting_coverage_baseline.toml",
        "--json",
    ]);

    assert!(
        output.status.success(),
        "porting coverage baseline failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let baseline = porting_coverage_baseline_toml();
    assert_eq!(
        parsed["passed"].as_i64(),
        baseline["coverage"]["passed"].as_integer()
    );
    assert_eq!(
        parsed["total"].as_i64(),
        baseline["coverage"]["total"].as_integer()
    );
    assert_eq!(
        parsed["result_count"].as_i64(),
        baseline["coverage"]["result_count"].as_integer()
    );
    assert_eq!(
        parsed["result_inventory_sha256"].as_str(),
        baseline["coverage"]["result_inventory_sha256"].as_str()
    );
    assert_eq!(parsed["baseline_errors"].as_array().unwrap().len(), 0);

    let baseline_by_kind = baseline["coverage"]["by_kind"].as_table().unwrap();
    let actual_by_kind = parsed["by_kind"].as_object().unwrap();
    assert_eq!(
        actual_by_kind.len(),
        baseline_by_kind.len(),
        "coverage baseline should enumerate every result kind"
    );
    for (kind, expected) in baseline_by_kind {
        let actual = actual_by_kind
            .get(kind)
            .unwrap_or_else(|| panic!("coverage baseline kind {kind} is missing"));
        assert_eq!(actual["passed"].as_i64(), expected["passed"].as_integer());
        assert_eq!(actual["total"].as_i64(), expected["total"].as_integer());
    }
}

#[test]
fn porting_coverage_rejects_denominator_baseline_drift() {
    let bad_baseline = r#"
[coverage]
passed = 1
total = 1
result_count = 1
result_inventory_sha256 = "bad"

[coverage.by_kind.layout]
passed = 1
total = 1

[porting_status]
total = 1
implemented = 1

[porting_status.by_status]
ported = 1
"#;
    let path = write_temp_file("porting-coverage-bad-baseline", bad_baseline);
    let output = run_porting_coverage(&["--coverage-baseline", path.to_str().unwrap()]);
    let _ = std::fs::remove_file(&path);

    assert!(
        !output.status.success(),
        "bad porting coverage baseline unexpectedly passed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stderr = String::from_utf8_lossy(&output.stderr);
    let baseline = porting_coverage_baseline_toml();
    let expected_total = baseline["coverage"]["total"].as_integer().unwrap();
    let expected_result_count = baseline["coverage"]["result_count"].as_integer().unwrap();
    assert!(stderr.contains("porting coverage baseline drift:"));
    assert!(stderr.contains(&format!(
        "coverage.total: expected baseline 1, got {expected_total}"
    )));
    assert!(stderr.contains(&format!(
        "coverage.result_count: expected baseline 1, got {expected_result_count}"
    )));
    assert!(stderr.contains("coverage.result_inventory_sha256: expected baseline bad"));
    assert!(
        stderr.contains("coverage.by_kind.behavior: actual report kind is missing from baseline")
    );
}

#[test]
fn firmware_ci_runs_complete_porting_gate_before_builds() {
    let gate_command = "cargo make porting-coverage";
    let migration_status_command = "python3 tools/migration_status.py";
    let baseline_arg = "--coverage-baseline";
    let zmk_required_flag = "--require-zmk-source";
    let zmk_commit_required_flag = "--require-zmk-source-commit";
    let complete_required_flag = "--require-porting-complete";
    let software_required_flag = "--require-software-complete";
    let host_tests = "cargo make host-parity-tests";
    let release_build = "cargo make build";
    let manifest = porting_coverage_manifest_toml();
    let source_commit = manifest["metadata"]["source_commit"].as_str().unwrap();
    let source_commit_ref = format!("ref: {source_commit}");

    for required in [
        gate_command,
        migration_status_command,
        baseline_arg,
        "tools/porting_coverage_baseline.toml",
        zmk_required_flag,
        zmk_commit_required_flag,
        source_commit_ref.as_str(),
        software_required_flag,
    ] {
        assert!(
            FIRMWARE_WORKFLOW_YAML.contains(required),
            "firmware CI is missing complete porting gate component {required:?}"
        );
    }

    let gate_index = FIRMWARE_WORKFLOW_YAML.find(gate_command).unwrap();
    let migration_status_index = FIRMWARE_WORKFLOW_YAML
        .find(migration_status_command)
        .unwrap();
    let host_tests_index = FIRMWARE_WORKFLOW_YAML.find(host_tests).unwrap();
    let release_build_index = FIRMWARE_WORKFLOW_YAML.find(release_build).unwrap();

    assert!(
        gate_index < migration_status_index,
        "runtime scenario coverage gate should run before migration status reporting"
    );
    assert!(
        gate_index < host_tests_index,
        "complete porting gate must run before host parity tests"
    );
    assert!(
        gate_index < release_build_index,
        "complete porting gate must run before release binaries are built"
    );

    let porting_coverage_task = makefile_task_block("porting-coverage");
    assert!(
        porting_coverage_task.contains(complete_required_flag)
            && porting_coverage_task.contains(zmk_commit_required_flag)
            && porting_coverage_task
                .contains("dependencies = [\"rmk-zmk-scenario-tests\", \"host-parity-tests\", \"rmk-behavior-tests\"]"),
        "cargo make porting-coverage should require the complete porting gate, runtime scenarios, host parity tests, and RMK behavior tests"
    );
}

#[test]
fn hardware_validation_manifest_is_classified_but_not_release_blocking() {
    let output = run_hardware_validation(&["--json", "--require-classified"]);

    assert!(
        output.status.success(),
        "hardware validation tracker failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let manifest = hardware_validation_manifest_toml();
    let checks = manifest["checks"].as_array().unwrap();
    let expected_total = checks.len() as i64;
    assert_eq!(parsed["total"].as_i64(), Some(expected_total));
    assert_eq!(parsed["classified"].as_bool(), Some(true));
    assert_eq!(parsed["errors"].as_array().unwrap().len(), 0);
    assert!(
        parsed["by_status"]["requires_hardware"].as_i64().unwrap() > 0,
        "real-hardware validation gaps should remain visible separately from source porting"
    );
    assert_eq!(parsed["by_area"]["trackpad"]["total"].as_i64(), Some(7));
    assert_eq!(parsed["by_area"]["trackpad"]["validated"].as_i64(), Some(0));
    assert_eq!(
        parsed["by_area"]["trackpad"]["by_status"]["requires_hardware"].as_i64(),
        Some(7)
    );
    assert_eq!(parsed["by_side"]["right"]["total"].as_i64(), Some(5));
    assert_eq!(parsed["by_side"]["left"]["total"].as_i64(), Some(3));
    assert_eq!(parsed["by_side"]["both"]["total"].as_i64(), Some(4));
    assert!(
        FIRMWARE_WORKFLOW_YAML.contains("python3 tools/hardware_validation.py")
            && FIRMWARE_WORKFLOW_YAML
                .contains("--hardware-baseline tools/hardware_validation_baseline.toml")
            && FIRMWARE_WORKFLOW_YAML.contains("--require-classified"),
        "firmware CI should keep the real-hardware validation tracker classified against the frozen baseline"
    );
    assert!(
        FIRMWARE_WORKFLOW_YAML.contains(
            "python3 tools/hardware_validation.py --markdown >> \"$GITHUB_STEP_SUMMARY\""
        ),
        "firmware CI should publish a hardware validation summary table"
    );
    assert!(
        !FIRMWARE_WORKFLOW_YAML.contains("--require-validated"),
        "release CI must not claim real-hardware validation without physical evidence"
    );

    let by_id: BTreeMap<_, _> = checks
        .iter()
        .map(|check| (check["id"].as_str().unwrap(), check))
        .collect();
    for (required_id, area, side) in [
        ("iqs9151_right_i2c_identity", "trackpad", "right"),
        ("iqs9151_left_i2c_identity", "trackpad", "left"),
        ("iqs9151_right_rdy_signal", "trackpad", "right"),
        ("iqs9151_left_rdy_signal", "trackpad", "left"),
        ("right_trackpad_cursor_tap_scroll", "trackpad", "right"),
        ("left_trackpad_split_cursor_tap_scroll", "trackpad", "left"),
        ("trackpad_drag_cross_side", "trackpad", "both"),
        ("ble_split_pairing_reconnect", "ble_split", "both"),
        ("vial_thumb_layer_taps", "vial", "both"),
        (
            "rgb_battery_connection_layer_indicators",
            "status_led",
            "right",
        ),
        ("charge_indicator_pins", "battery", "right"),
        ("storage_reset_and_reflash", "storage", "both"),
    ] {
        let check = by_id
            .get(required_id)
            .unwrap_or_else(|| panic!("hardware validation check {required_id} is missing"));
        assert_eq!(check["area"].as_str(), Some(area));
        assert_eq!(check["side"].as_str(), Some(side));
    }
}

