#[test]
fn hardware_validation_reports_required_observations_in_json_and_text() {
    let json = run_hardware_validation(&["--json"]);
    let text = run_hardware_validation(&[]);

    assert!(
        json.status.success(),
        "hardware validation json report failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&json.stdout),
        String::from_utf8_lossy(&json.stderr)
    );
    assert!(
        text.status.success(),
        "hardware validation text report failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&text.stdout),
        String::from_utf8_lossy(&text.stderr)
    );

    let parsed: serde_json::Value = serde_json::from_slice(&json.stdout).unwrap();
    let right_trackpad = parsed["remaining"]
        .as_array()
        .unwrap()
        .iter()
        .find(|item| item["id"] == "right_trackpad_cursor_tap_scroll")
        .expect("right trackpad remaining item is missing");
    assert_eq!(
        right_trackpad["evidence_needles"].as_str(),
        Some(
            "right, cursor, tap, vertical scroll, horizontal scroll, no cursor during scroll, no right-click during scroll, inertia continues, inertia stops on touch"
        )
    );

    let text_stdout = String::from_utf8_lossy(&text.stdout);
    assert!(
        text_stdout
            .contains("right_trackpad_cursor_tap_scroll (trackpad/right): requires_hardware")
    );
    assert!(text_stdout.contains(
        "[needs: right, cursor, tap, vertical scroll, horizontal scroll, no cursor during scroll, no right-click during scroll, inertia continues, inertia stops on touch]"
    ));
}

#[test]
fn firmware_artifact_manifest_hashes_release_artifacts() {
    let output = run_python(
        r#"
import hashlib
import json
import subprocess
import sys
import tempfile
import zipfile
from pathlib import Path

with tempfile.TemporaryDirectory() as tempdir:
    root = Path(tempdir)
    files = {
        "firmware/normal/lalapad-gen2-rmk-central.uf2": b"central uf2",
        "firmware/normal/lalapad-gen2-rmk-peripheral.uf2": b"peripheral uf2",
        "firmware/hex/lalapad-gen2-rmk-central.hex": b":central\n",
        "firmware/hex/lalapad-gen2-rmk-peripheral.hex": b":peripheral\n",
    }
    for path, contents in files.items():
        target = root / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(contents)
    for role in ["central", "peripheral"]:
        target = root / f"firmware/lalapad-gen2-rmk-{role}-dfu.zip"
        with zipfile.ZipFile(target, "w") as archive:
            archive.writestr(
                "manifest.json",
                json.dumps({"manifest": {"application": {"bin_file": f"{role}.bin", "dat_file": f"{role}.dat"}}}),
            )

    output_path = root / "firmware-artifacts.local.json"
    manifest = subprocess.run(
        [
            sys.executable,
            "tools/firmware_artifact_manifest.py",
            "--root",
            str(root),
            "--firmware-ref",
            "v0.3.0",
            "--require-uf2",
            "--require-dfu",
            "--output",
            str(output_path),
        ],
        check=True,
        cwd=Path.cwd(),
        stdout=subprocess.PIPE,
        text=True,
    )
    parsed = json.loads(output_path.read_text())
    output_path_exists = output_path.exists()

    missing = root / "firmware/normal/lalapad-gen2-rmk-peripheral.uf2"
    missing.unlink()
    stale_output = root / "stale-firmware-artifacts.local.json"
    stale_output.write_text("stale\n")
    failed = subprocess.run(
        [
            sys.executable,
            "tools/firmware_artifact_manifest.py",
            "--root",
            str(root),
            "--firmware-ref",
            "v0.3.0",
            "--require-uf2",
            "--output",
            str(stale_output),
        ],
        cwd=Path.cwd(),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )

print(json.dumps({
    "manifest": parsed,
    "stdout": manifest.stdout,
    "output_path_exists": output_path_exists,
    "central_uf2_sha256": hashlib.sha256(b"central uf2").hexdigest(),
    "failed_code": failed.returncode,
    "failed_stdout": failed.stdout,
    "failed_stderr": failed.stderr,
    "stale_output_exists_after_failure": stale_output.exists(),
}))
"#,
    );

    assert!(
        output.status.success(),
        "firmware artifact manifest script failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let manifest = &parsed["manifest"];
    assert_eq!(parsed["stdout"].as_str(), Some(""));
    assert_eq!(parsed["output_path_exists"].as_bool(), Some(true));
    assert_eq!(manifest["firmware_ref"].as_str(), Some("v0.3.0"));
    assert_eq!(manifest["artifact_count"].as_i64(), Some(6));
    assert!(
        manifest["pair_sha256"]
            .as_str()
            .is_some_and(|value| value.len() == 64)
    );
    let central_uf2 = manifest["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|artifact| artifact["path"] == "firmware/normal/lalapad-gen2-rmk-central.uf2")
        .expect("central UF2 artifact is missing");
    assert_eq!(central_uf2["role"].as_str(), Some("central"));
    assert_eq!(central_uf2["side"].as_str(), Some("right"));
    assert_eq!(central_uf2["kind"].as_str(), Some("uf2"));
    assert_eq!(central_uf2["size"].as_i64(), Some(11));
    assert_eq!(
        central_uf2["sha256"].as_str(),
        parsed["central_uf2_sha256"].as_str()
    );
    let central_dfu = manifest["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|artifact| artifact["path"] == "firmware/lalapad-gen2-rmk-central-dfu.zip")
        .expect("central DFU artifact is missing");
    assert_eq!(central_dfu["dfu_manifest"]["valid"].as_bool(), Some(true));
    assert_eq!(
        central_dfu["dfu_manifest"]["application"]["bin_file"].as_str(),
        Some("central.bin")
    );
    assert_ne!(parsed["failed_code"].as_i64(), Some(0));
    assert_eq!(parsed["failed_stdout"].as_str(), Some(""));
    assert_eq!(
        parsed["stale_output_exists_after_failure"].as_bool(),
        Some(false)
    );
    assert!(
        parsed["failed_stderr"]
            .as_str()
            .unwrap()
            .contains("missing required artifact: firmware/normal/lalapad-gen2-rmk-peripheral.uf2")
    );
}

#[test]
fn hardware_validation_requires_valid_source_anchors() {
    let manifest = r#"
[[checks]]
id = "bad_source"
area = "trackpad"
side = "right"
requirement = "A hardware-only behavior is documented."
evidence = "Run the documented hardware check."
evidence_needles = ["documented", "hardware"]
source = "docs/TRACKPAD_HARDWARE_CHECK.md#missing-heading"
status = "requires_hardware"
"#;
    let path = write_temp_file("hardware-validation-bad-source", manifest);
    let output =
        run_hardware_validation(&["--manifest", path.to_str().unwrap(), "--require-classified"]);
    let _ = std::fs::remove_file(&path);

    assert!(
        !output.status.success(),
        "bad hardware source link unexpectedly passed --require-classified\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        String::from_utf8_lossy(&output.stderr)
            .contains("bad_source: source anchor #missing-heading was not found"),
        "bad hardware source link should explain the missing anchor"
    );
}

