#[test]
fn hardware_validation_rejects_validated_evidence_missing_required_observations() {
    let evidence = r#"
[[evidence]]
id = "right_trackpad_cursor_tap_scroll"
status = "validated"
validated_at = "2026-05-29"
tester = "hardware bench"
firmware_ref = "35b3f1f"
artifact_or_notes = "video: /tmp/right-trackpad.mp4; right cursor and tap worked during the run."

[[evidence]]
id = "vial_thumb_layer_taps"
status = "validated"
validated_at = "2026-05-29"
tester = "hardware bench"
firmware_ref = "35b3f1f"
artifact_or_notes = "photo: /tmp/vial.png; Vial screenshot shows Spacebar Entertainer layer 10 layer 20 labels."

[[evidence]]
id = "iqs9151_left_i2c_identity"
status = "validated"
validated_at = "2026-05-29"
tester = "hardware bench"
firmware_ref = "35b3f1f"
artifact_or_notes = "log: /tmp/right-i2c.log; I2C scan found 0x56 and product register 0x1000 read 0x09bc on the right half."

[[evidence]]
id = "ble_split_pairing_reconnect"
status = "validated"
validated_at = "2026-05-29"
tester = "hardware bench"
firmware_ref = "35b3f1f"
artifact_or_notes = "video: /tmp/ble-split.mp4; BLE pair and reconnect worked with right central key input only."

[[evidence]]
id = "storage_reset_and_reflash"
status = "validated"
validated_at = "2026-05-29"
tester = "hardware bench"
firmware_ref = "35b3f1f"
artifact_or_notes = "video: /tmp/storage-reset.mp4; flashed reset central UF2 and normal central UF2, then re-pair BLE and opened Vial."
"#;
    let path = write_temp_file("hardware-validation-missing-observations", evidence);
    let output = run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--json"]);
    let require_output =
        run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--require-classified"]);
    let _ = std::fs::remove_file(&path);

    assert!(
        output.status.success(),
        "missing observation json report failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(parsed["validated"].as_i64(), Some(0));
    let errors: Vec<_> = parsed["errors"]
        .as_array()
        .unwrap()
        .iter()
        .map(|error| error.as_str().unwrap())
        .collect();
    assert!(
        errors.iter().any(|error| {
            error.contains("artifact_or_notes must mention required observation(s)")
                && error.contains("'vertical scroll'")
                && error.contains("'horizontal scroll'")
                && error.contains("'no cursor during scroll'")
                && error.contains("'no right-click during scroll'")
                && error.contains("'inertia continues'")
                && error.contains("'inertia stops on touch'")
        }),
        "missing scroll and inertia observations should be rejected: {errors:?}"
    );
    assert!(
        errors.iter().any(|error| {
            error.contains(
                "vial_thumb_layer_taps: artifact_or_notes must mention required observation(s)",
            ) && error.contains("'Space'")
                && error.contains("'Enter'")
                && error.contains("'layer 1'")
                && error.contains("'layer 2'")
                && error.contains("'Space+Y'")
                && error.contains("'NumLock'")
                && error.contains("'Enter+Y'")
                && error.contains("'PageUp'")
        }),
        "required observations should not match inside larger words or numbers: {errors:?}"
    );
    assert!(
        errors.iter().any(|error| {
            error.contains(
                "iqs9151_left_i2c_identity: artifact_or_notes must mention required observation(s)",
            ) && error.contains("'left'")
        }),
        "left IQS9151 identity should require left-side evidence instead of accepting a right-side log: {errors:?}"
    );
    assert!(
        errors.iter().any(|error| {
            error.contains(
                "ble_split_pairing_reconnect: artifact_or_notes must mention required observation(s)",
            ) && error.contains("'left peripheral'")
                && error.contains("'BLE re-pair'")
                && error.contains("'reconnect right first'")
                && error.contains("'left Q'")
                && error.contains("'left A'")
                && error.contains("'right Y'")
                && error.contains("'right H'")
        }),
        "BLE split reconnect evidence should require concrete left/right key observations: {errors:?}"
    );
    assert!(
        errors.iter().any(|error| {
            error.contains(
                "storage_reset_and_reflash: artifact_or_notes must mention required observation(s)",
            ) && error.contains("'reset peripheral UF2'")
                && error.contains("'normal peripheral UF2'")
        }),
        "storage reset evidence should require both reset and normal UF2 observations for the peripheral half: {errors:?}"
    );
    assert!(
        !require_output.status.success(),
        "incomplete hardware observations unexpectedly passed --require-classified"
    );
}

#[test]
fn hardware_validation_can_require_matching_firmware_ref() {
    let evidence = r#"
[[evidence]]
id = "iqs9151_right_i2c_identity"
status = "validated"
validated_at = "2026-05-29"
tester = "hardware bench"
firmware_ref = "35b3f1f"
artifact_or_notes = "I2C scan found 0x56 and product register 0x1000 read 0x09bc on the right half."
"#;
    let path = write_temp_file("hardware-validation-firmware-ref", evidence);
    let ok = run_hardware_validation(&[
        "--evidence",
        path.to_str().unwrap(),
        "--require-firmware-ref",
        "35b3f1f",
    ]);
    let bad = run_hardware_validation(&[
        "--evidence",
        path.to_str().unwrap(),
        "--require-firmware-ref",
        "v0.2.64",
    ]);
    let _ = std::fs::remove_file(&path);

    assert!(
        ok.status.success(),
        "matching firmware_ref should pass\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&ok.stdout),
        String::from_utf8_lossy(&ok.stderr)
    );
    assert!(
        !bad.status.success(),
        "mismatched firmware_ref unexpectedly passed"
    );
    assert!(
        String::from_utf8_lossy(&bad.stderr)
            .contains("validated firmware_ref '35b3f1f' does not match required 'v0.2.64'"),
        "mismatched firmware_ref should explain the stale evidence"
    );
}

#[test]
fn hardware_validation_requires_firmware_ref_for_validated_evidence() {
    let evidence = r#"
[[evidence]]
id = "iqs9151_right_i2c_identity"
status = "validated"
validated_at = "2026-05-29"
tester = "hardware bench"
artifact_or_notes = "missing firmware_ref should not count"
"#;
    let path = write_temp_file("hardware-validation-missing-firmware-ref", evidence);
    let output = run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--json"]);
    let require_output =
        run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--require-classified"]);
    let _ = std::fs::remove_file(&path);

    assert!(
        output.status.success(),
        "missing firmware_ref json report failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(parsed["validated"].as_i64(), Some(0));
    assert_eq!(parsed["classified"].as_bool(), Some(false));
    assert_eq!(
        parsed["remaining"][0]["status"].as_str(),
        Some("validated_invalid")
    );
    assert_eq!(parsed["by_area"]["trackpad"]["validated"].as_i64(), Some(0));
    assert_eq!(
        parsed["by_area"]["trackpad"]["by_status"]["validated"].as_i64(),
        Some(1)
    );
    assert_eq!(parsed["by_side"]["right"]["validated"].as_i64(), Some(0));
    assert_eq!(
        parsed["by_side"]["right"]["by_status"]["validated"].as_i64(),
        Some(1)
    );
    assert!(
        parsed["errors"].as_array().unwrap()[0]
            .as_str()
            .unwrap()
            .contains("validated checks require evidence field(s): firmware_ref")
    );
    assert!(
        !require_output.status.success(),
        "missing firmware_ref unexpectedly passed --require-classified"
    );
}

