#[test]
fn hardware_validation_can_generate_complete_evidence_template() {
    let output = run_hardware_validation(&["--evidence-template"]);

    assert!(
        output.status.success(),
        "hardware validation evidence template generation failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    let generated: toml::Value = toml::from_str(&stdout).unwrap();
    let template_entries = generated["evidence"].as_array().unwrap();
    let manifest = hardware_validation_manifest_toml();
    let checks = manifest["checks"].as_array().unwrap();
    assert_eq!(template_entries.len(), checks.len());
    for check in checks {
        let check_id = check["id"].as_str().unwrap();
        let entry = template_entries
            .iter()
            .find(|entry| entry["id"].as_str() == Some(check_id))
            .unwrap_or_else(|| panic!("evidence template missing {check_id}"));
        assert_eq!(entry["status"].as_str(), Some("requires_hardware"));
        assert_eq!(entry["validated_at"].as_str(), Some(""));
        assert_eq!(entry["tester"].as_str(), Some(""));
        assert_eq!(entry["firmware_ref"].as_str(), Some(""));
        assert_eq!(entry["artifact_or_notes"].as_str(), Some(""));
        assert!(
            stdout.contains(check["requirement"].as_str().unwrap()),
            "evidence template should include requirement comments for {check_id}"
        );
        assert!(
            stdout.contains(check["evidence"].as_str().unwrap()),
            "evidence template should include evidence instructions for {check_id}"
        );
        assert!(
            stdout.contains(check["source"].as_str().unwrap()),
            "evidence template should include source comments for {check_id}"
        );
        for needle in check["evidence_needles"].as_array().unwrap() {
            assert!(
                stdout.contains(needle.as_str().unwrap()),
                "evidence template should include required observation needle for {check_id}"
            );
        }
    }

    let path = write_temp_file("hardware-validation-template", &stdout);
    let overlay_output = run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--json"]);
    let _ = std::fs::remove_file(&path);
    assert!(
        overlay_output.status.success(),
        "generated evidence template should be a valid non-progress overlay\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&overlay_output.stdout),
        String::from_utf8_lossy(&overlay_output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&overlay_output.stdout).unwrap();
    assert_eq!(parsed["validated"].as_i64(), Some(0));
    assert_eq!(parsed["classified"].as_bool(), Some(true));
}

#[test]
fn hardware_validation_can_generate_bench_checklist() {
    let output = run_hardware_validation(&["--checklist"]);

    assert!(
        output.status.success(),
        "hardware validation checklist generation failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    let manifest = hardware_validation_manifest_toml();
    let checks = manifest["checks"].as_array().unwrap();
    assert!(stdout.contains("# LaLaPad Gen2 RMK Hardware Validation Checklist"));
    assert!(stdout.contains("Record the flashed firmware tag or commit before testing."));
    assert!(stdout.contains("firmware-artifacts.local.json"));
    assert!(stdout.contains("pair_sha256"));
    assert!(stdout.contains("## trackpad"));
    assert!(stdout.contains("## vial"));
    for check in checks {
        let check_id = check["id"].as_str().unwrap();
        assert!(
            stdout.contains(&format!("- [ ] `{check_id}`")),
            "checklist should include checkbox for {check_id}"
        );
        assert!(
            stdout.contains(check["requirement"].as_str().unwrap()),
            "checklist should include requirement for {check_id}"
        );
        assert!(
            stdout.contains(check["evidence"].as_str().unwrap()),
            "checklist should include evidence instructions for {check_id}"
        );
        assert!(
            stdout.contains(&format!("    - id: {check_id}")),
            "checklist should include evidence overlay id for {check_id}"
        );
        assert!(
            stdout.contains("status: validated only after this item passes on hardware"),
            "checklist should warn that validated is only for passing hardware evidence"
        );
        assert!(
            stdout.contains("firmware_ref: flashed immutable tag or commit"),
            "checklist should include firmware_ref capture guidance"
        );
        assert!(
            stdout.contains(
                "artifact_or_notes: concrete photo/log/probe/Vial observation that mentions"
            ),
            "checklist should include artifact_or_notes capture guidance"
        );
        for needle in check["evidence_needles"].as_array().unwrap() {
            assert!(
                stdout.contains(needle.as_str().unwrap()),
                "checklist should include required observation needle for {check_id}"
            );
        }
    }

    let bad_mix = run_hardware_validation(&["--checklist", "--markdown"]);
    assert!(
        !bad_mix.status.success(),
        "--checklist and --markdown should be mutually exclusive"
    );
    assert!(
        String::from_utf8_lossy(&bad_mix.stderr).contains("--checklist"),
        "exclusive output mode error should mention --checklist"
    );
}

#[test]
fn hardware_validation_evidence_template_can_prefill_firmware_ref() {
    let pair_sha256 = "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc";
    let output = run_hardware_validation(&[
        "--evidence-template",
        "--firmware-ref-template",
        "v0.2.66",
        "--artifact-pair-sha256-template",
        pair_sha256,
    ]);

    assert!(
        output.status.success(),
        "hardware validation evidence template with firmware ref failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    let generated: toml::Value = toml::from_str(&stdout).unwrap();
    let template_entries = generated["evidence"].as_array().unwrap();
    let manifest = hardware_validation_manifest_toml();
    assert_eq!(
        template_entries.len(),
        manifest["checks"].as_array().unwrap().len()
    );
    assert!(
        template_entries
            .iter()
            .all(|entry| entry["firmware_ref"].as_str() == Some("v0.2.66")),
        "all template entries should prefill the requested firmware_ref"
    );
    assert!(
        template_entries
            .iter()
            .all(|entry| entry["artifact_or_notes"]
                .as_str()
                .unwrap()
                .contains(pair_sha256)),
        "all template entries should prefill the requested artifact pair SHA256"
    );
}

#[test]
fn hardware_validation_rejects_template_firmware_ref_without_template_output() {
    let output = run_hardware_validation(&[
        "--manifest",
        "/tmp/lalapad-missing-hardware-validation.toml",
        "--firmware-ref-template",
        "v0.2.66",
    ]);

    assert!(
        !output.status.success(),
        "--firmware-ref-template without --evidence-template unexpectedly passed"
    );
    assert!(
        String::from_utf8_lossy(&output.stderr)
            .contains("--firmware-ref-template can only be used with --evidence-template"),
        "invalid firmware_ref template usage should explain the required output mode"
    );
    assert!(
        !String::from_utf8_lossy(&output.stderr).contains("No such file"),
        "invalid firmware_ref template usage should fail before reading manifest files"
    );

    let artifact_pair_output = run_hardware_validation(&[
        "--manifest",
        "/tmp/lalapad-missing-hardware-validation.toml",
        "--artifact-pair-sha256-template",
        "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc",
    ]);
    assert!(
        !artifact_pair_output.status.success(),
        "--artifact-pair-sha256-template without --evidence-template unexpectedly passed"
    );
    assert!(
        String::from_utf8_lossy(&artifact_pair_output.stderr)
            .contains("--artifact-pair-sha256-template can only be used with --evidence-template"),
        "invalid artifact pair template usage should explain the required output mode"
    );
    assert!(
        !String::from_utf8_lossy(&artifact_pair_output.stderr).contains("No such file"),
        "invalid artifact pair template usage should fail before reading manifest files"
    );
}

#[test]
fn hardware_validation_does_not_count_incomplete_validated_evidence() {
    let evidence = r#"
[[evidence]]
id = "iqs9151_right_i2c_identity"
status = "validated"
validated_at = "2026-05-29"
artifact_or_notes = "missing tester should not count"
"#;
    let path = write_temp_file("hardware-validation-incomplete-evidence", evidence);
    let output = run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--json"]);
    let _ = std::fs::remove_file(&path);

    assert!(
        output.status.success(),
        "incomplete hardware evidence json report failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(parsed["validated"].as_i64(), Some(0));
    assert_eq!(parsed["classified"].as_bool(), Some(false));
    assert_eq!(
        parsed["remaining"][0]["id"].as_str(),
        Some("iqs9151_right_i2c_identity")
    );
    assert_eq!(
        parsed["remaining"][0]["status"].as_str(),
        Some("validated_invalid")
    );
    assert!(
        parsed["errors"].as_array().unwrap()[0]
            .as_str()
            .unwrap()
            .contains("validated checks require evidence field(s): tester")
    );

    let require_output =
        run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--require-classified"]);
    assert!(
        !require_output.status.success(),
        "incomplete hardware evidence unexpectedly passed --require-classified"
    );
}

#[test]
fn hardware_validation_rejects_placeholder_or_vague_validated_evidence() {
    let evidence = r#"
[[evidence]]
id = "iqs9151_right_i2c_identity"
status = "validated"
validated_at = "2026-13-40"
tester = "tester"
firmware_ref = "<tag-or-commit>"
artifact_or_notes = "TODO"

[[evidence]]
id = "iqs9151_left_i2c_identity"
status = "validated"
validated_at = "2999-01-01"
tester = "name"
firmware_ref = "main"
artifact_or_notes = "tested ok on hardware"

[[evidence]]
id = "vial_thumb_layer_taps"
status = "validated"
validated_at = "2026-05-29"
tester = "bench operator"
firmware_ref = "35b3f1f"
artifact_or_notes = "manual observation completed"

[[evidence]]
id = "right_trackpad_cursor_tap_scroll"
status = "validated"
validated_at = "2026-05-29"
tester = "bench operator"
firmware_ref = "35b3f1f"
artifact_or_notes = "right cursor tap vertical scroll horizontal scroll"

[[evidence]]
id = "left_trackpad_split_cursor_tap_scroll"
status = "validated"
validated_at = "2026-05-29"
tester = "bench operator"
firmware_ref = "35b3f1f"
artifact_or_notes = "TODO log: /tmp/left-trackpad.log; left split cursor tap vertical scroll horizontal scroll no cursor during scroll no right-click during scroll inertia continues inertia stops on touch"
"#;
    let path = write_temp_file("hardware-validation-placeholder-evidence", evidence);
    let output = run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--json"]);
    let require_output =
        run_hardware_validation(&["--evidence", path.to_str().unwrap(), "--require-classified"]);
    let _ = std::fs::remove_file(&path);

    assert!(
        output.status.success(),
        "placeholder hardware evidence json report failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let parsed: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(parsed["validated"].as_i64(), Some(0));
    assert_eq!(parsed["classified"].as_bool(), Some(false));
    let errors: Vec<_> = parsed["errors"]
        .as_array()
        .unwrap()
        .iter()
        .map(|error| error.as_str().unwrap())
        .collect();
    assert!(
        errors
            .iter()
            .any(|error| error.contains("validated_at must be a real calendar date")),
        "invalid calendar date should be rejected: {errors:?}"
    );
    assert!(
        errors
            .iter()
            .any(|error| error.contains("validated_at must not be in the future")),
        "future validation date should be rejected: {errors:?}"
    );
    assert!(
        errors
            .iter()
            .any(|error| error.contains("tester must identify the person or bench")),
        "placeholder tester should be rejected: {errors:?}"
    );
    assert!(
        errors
            .iter()
            .any(|error| error.contains("firmware_ref must be the actual flashed tag or commit")),
        "placeholder firmware_ref should be rejected: {errors:?}"
    );
    assert!(
        errors
            .iter()
            .any(|error| error.contains("artifact_or_notes must describe the observed evidence")),
        "placeholder artifact_or_notes should be rejected: {errors:?}"
    );
    assert!(
        errors.iter().any(|error| error.contains(
            "artifact_or_notes must include a concrete photo/log/probe/Vial observation note"
        )),
        "generic artifact_or_notes without a concrete signal should be rejected: {errors:?}"
    );
    assert!(
        errors.iter().any(|error| error.contains(
            "right_trackpad_cursor_tap_scroll: artifact_or_notes must include a concrete photo/log/probe/Vial observation note"
        )),
        "behavior keywords alone should not count as concrete hardware evidence: {errors:?}"
    );
    assert!(
        errors.iter().any(|error| error.contains(
            "left_trackpad_split_cursor_tap_scroll: artifact_or_notes must not contain placeholder markers"
        )),
        "artifact_or_notes with TODO marker should not count even if it has a log path and all required observations: {errors:?}"
    );
    assert!(
        !require_output.status.success(),
        "placeholder hardware evidence unexpectedly passed --require-classified"
    );
}

